    """ For a given list of input numbers, return Median.
    Median is the middle number in a sorted list of numbers. If there is
    an even amount of numbers in a list then median is the median value between the middle numbers.
    >>> median([1.0, 3.0, 4.0, 5.0, 5.0, 7.0])
    4.0
    """
    sorted_numbers = sorted(numbers)
    middle_index = len(numbers) // 2
    # Even length list, median is index middle + 1/2th of middle range
    middle_number_index = middle_index - len(numbers) % 2
    return (
        (
            sorted_numbers[middle_number_index] + sorted_numbers[middle_number_index + 1]
        ) / 2
        if middle_number_index
        else sorted_numbers[middle_index]
    )


